insert into public.stories (id, owner_id, visibility, status, draft_title, draft_body, draft_summary, language, grade_level, topic, revision)
values ($seed$00000000-0000-4000-8000-000000000103$seed$, null, 'library', 'published', $seed$The Red Kite$seed$, $seed$Ben and his sister Mia made a red kite. They used paper, sticks, and a long string.

On Saturday, the wind was strong. Ben held the string and Mia ran across the field. The kite went up, up, up into the sky.

Suddenly, the string slipped from Ben's hand. The kite flew over the trees! Ben felt sad.

Mia smiled. "We can make another kite," she said. "This time, we will hold the string together."$seed$, $seed$Ben and Mia make a kite and learn to work together.$seed$, $seed$en$seed$, 2, $seed$Family$seed$, 1)
on conflict (id) do nothing;
insert into public.stories (id, owner_id, visibility, status, draft_title, draft_body, draft_summary, language, grade_level, topic, revision)
values ($seed$00000000-0000-4000-8000-000000000104$seed$, null, 'library', 'published', $seed$Lola's Garden$seed$, $seed$Every morning, Lola Rosa waters her garden before the sun gets too hot. She grows tomatoes, eggplants, and tall green string beans.

Carlo likes to help his grandmother. He pulls the weeds and checks the leaves for hungry caterpillars. Lola Rosa tells him that a garden needs patience. "Plants grow a little every day," she says, "even when we cannot see it."

One week, the rain did not come. The soil became dry and cracked. Carlo carried buckets of water from the well, one slow trip at a time.

At last, the first tomato turned red. Carlo picked it carefully and shared it with Lola Rosa. It was the sweetest tomato he had ever tasted.$seed$, $seed$Carlo helps his grandmother care for her garden during a dry week.$seed$, $seed$en$seed$, 3, $seed$Nature$seed$, 1)
on conflict (id) do nothing;
insert into public.stories (id, owner_id, visibility, status, draft_title, draft_body, draft_summary, language, grade_level, topic, revision)
values ($seed$00000000-0000-4000-8000-000000000105$seed$, null, 'library', 'published', $seed$Ang Pusa ni Lito$seed$, $seed$May pusa si Lito. Ang pangalan niya ay Muning. Puti at itim ang balahibo ni Muning.

Gusto ni Muning ang maglaro ng bola. Gusto rin niya ang matulog sa araw.

Tuwing gabi, katabi ni Lito si Muning sa kama. Mahal na mahal ni Lito ang kanyang pusa.$seed$, $seed$Si Lito at ang kanyang pusang si Muning.$seed$, $seed$fil$seed$, 1, $seed$Hayop$seed$, 1)
on conflict (id) do nothing;
insert into public.stories (id, owner_id, visibility, status, draft_title, draft_body, draft_summary, language, grade_level, topic, revision)
values ($seed$00000000-0000-4000-8000-000000000106$seed$, null, 'library', 'published', $seed$Sa Palengke$seed$, $seed$Maagang gumising si Nena. Sasama siya kay Nanay sa palengke.

Maraming tao sa palengke. May nagtitinda ng isda, gulay, at prutas. Bumili si Nanay ng kamatis, sibuyas, at isang kilong bigas.

"Nanay, puwede po ba tayong bumili ng mangga?" tanong ni Nena. Ngumiti si Nanay at bumili sila ng tatlong hinog na mangga.

Pag-uwi nila, tinulungan ni Nena si Nanay na ayusin ang mga pinamili.$seed$, $seed$Sumama si Nena kay Nanay sa palengke.$seed$, $seed$fil$seed$, 2, $seed$Pamayanan$seed$, 1)
on conflict (id) do nothing;

